local Controller=include("rhenium_hot_object_round/controller.lua");local Server={HookPrefix="RheniumHotObjectRound",TimerName="RheniumHotObjectRound.Tick"};local core,installed=nil,false;local players,objects={},{};local sequence=0
local function validp(p)return IsValid(p)and p:IsPlayer()end
local function player_binding(p)return players[p]end
local function validid(v)return type(v)=="string"and#v>0 and#v<=128 and v:match("^[%w][%w_.:%-]*$")~=nil end
local function validrev(v)return type(v)=="number"and v>=1 and v%1==0 and v<math.huge end
local function restore(e,b)if b then e.StartTouch=b.old_start;e.Touch=b.old_touch end end
function Server.Install(o)if installed then return Server end;o=o or{};core=assert(Controller.new({object_id=o.object_id or"hot:1",object_revision=o.object_revision or 1,state=o.state}));hook.Add("PlayerDeath",Server.HookPrefix..".Death",function(p)local b=player_binding(p);if b then core:death("death:"..b.id..":"..b.revision,b.id,b.revision,CurTime())end end);hook.Add("PlayerSpawn",Server.HookPrefix..".Spawn",function(p)local b=player_binding(p);if b and b.spawned then local old=b.revision;b.revision=old+1;core:respawn("respawn:"..b.id..":"..b.revision,b.id,old,b.revision,CurTime())elseif b then b.spawned=true end end);hook.Add("PlayerDisconnected",Server.HookPrefix..".Disconnect",function(p)local b=player_binding(p);if b then core:disconnect("disconnect:"..b.id..":"..b.revision,b.id,b.revision,CurTime())end;players[p]=nil end);hook.Add("EntityRemoved",Server.HookPrefix..".Removed",function(e)local b=objects[e];restore(e,b);objects[e]=nil end);timer.Create(Server.TimerName,.05,0,function()if core then core:tick(CurTime())end end);installed=true;return Server end
function Server.BindPlayer(p,id,revision)revision=revision or 1;if not installed or not validp(p)or not validid(id)or not validrev(revision)then return false end;players[p]={id=id,revision=revision,spawned=true};return true end
function Server.BindObject(e,id,revision)if not installed or not IsValid(e)or not validid(id)or not validrev(revision)or objects[e]then return false end;local b={id=id,revision=revision,old_start=e.StartTouch,old_touch=e.Touch};objects[e]=b;e.StartTouch=function(self,other)if b.old_start then b.old_start(self,other)end;Server.Dispatch({kind="touch",object=self,player=other})end;e.Touch=function(self,other)if b.old_touch then b.old_touch(self,other)end;Server.Dispatch({kind="touch",object=self,player=other})end;return true end
function Server.StartRound(rid,round_id,variant,list,holder,deadline)local ids={};for _,p in ipairs(list)do local b=players[p];if not b then return false,"unbound",{}end;ids[#ids+1]=b.id end;local h=players[holder];if not h then return false,"unbound",{}end;return core:start(rid,round_id,variant,ids,h.id,deadline)end
function Server.Dispatch(e)if type(e)~="table"then return false,"invalid_event",{}end;if e.kind=="touch"then local o,p=objects[e.object],players[e.player];if not o or not p then return false,"unbound",{}end;sequence=sequence+1;return core:touch(e.event_id or("touch:"..sequence),o.id,o.revision,p.id,p.revision,e.sequence or sequence,e.now or CurTime())elseif e.kind=="death"then local p=players[e.player];return p and core:death(e.event_id,p.id,p.revision,e.now or CurTime())or false,"unbound",{}elseif e.kind=="disconnect"then local p=players[e.player];return p and core:disconnect(e.event_id,p.id,p.revision,e.now or CurTime())or false,"unbound",{}end;return false,"invalid_kind",{}end
function Server.Snapshot()return core and core:snapshot(CurTime())end;function Server.Save()return core and core:save(CurTime())end
function Server.Shutdown()if installed then for _,x in ipairs({{"PlayerDeath",".Death"},{"PlayerSpawn",".Spawn"},{"PlayerDisconnected",".Disconnect"},{"EntityRemoved",".Removed"}})do hook.Remove(x[1],Server.HookPrefix..x[2])end;timer.Remove(Server.TimerName);installed=false end;for e,b in pairs(objects)do restore(e,b)end;if core then core:shutdown()end;players={};objects={};sequence=0;return true,"shutdown"end;return Server
